SELECT 
FROM biz_company_domain d
INNER JOIN biz_company c ON c.company_id = d.company_id


        AND d.company_id = #{companyId}


        AND d.host_name ILIKE CONCAT('%', #{hostName}, '%')


        AND d.use_yn = #{useYn}


ORDER BY d.primary_yn DESC, d.domain_id DESC
LIMIT #{limit}

